-- =====================================================================================================
--  BillPoodum — Turso (libSQL / SQLite) schema: platform database (one)
-- =====================================================================================================
--  GENERATED by backend/scripts/gen-sqlite.mjs from server/catalyst/schema.sql — do not edit by hand.
--  To change a table: edit schema.sql, run the generator, and add the difference as a new migration file
--  backend/migrations/platform/NNNN_<what>.sql (ALTER TABLE …). The tests check the migrations add up to this file.
--
--  Same tables, columns and relations as the approved design (see server/catalyst/TABLES.md). Mapping:
--    Catalyst ROWID              → "id" INTEGER PRIMARY KEY AUTOINCREMENT (never reused; the API calls it ROWID)
--    CREATEDTIME / MODIFIEDTIME  → "created_at" / "updated_at"  TEXT, ISO-8601 UTC (set automatically)
--    VARCHAR(n) / TEXT           → TEXT  (max length checked by the API, so it can grow without a table rebuild)
--    INT / BIGINT / FK ids       → INTEGER   · money in paise, qty in thousandths, % in basis points
--    BOOLEAN                     → INTEGER 0 / 1
--    DATE / DATETIME             → TEXT  YYYY-MM-DD / ISO-8601 UTC (sorts and compares correctly)
--    ENCRYPTED                   → TEXT holding AES-256-GCM ciphertext (the API encrypts with SECRETS_KEY)
--    Fixed lists (enums)         → INTEGER codes from server/catalyst/enums.ts (CHECK >= 1 only, so a new
--                                   value never needs a migration). Never renumber; add at the end.
--    FK → x CASCADE / NULL       → REFERENCES x("id") ON DELETE CASCADE / SET NULL — only when x is in this
--                                   database; a reference to the other database is a plain INTEGER.
--  The API turns on foreign keys ("PRAGMA foreign_keys = ON") on every connection.
-- =====================================================================================================

CREATE TABLE IF NOT EXISTS "platform_admins" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "name"                     TEXT     NOT NULL,  -- max 120
  "username"                 TEXT     NOT NULL UNIQUE,  -- max 40
  "email"                    TEXT,  -- max 150
  "password_hash"            TEXT     NOT NULL,  -- max 100 · bcrypt
  "token_version"            INTEGER  NOT NULL DEFAULT 1,  -- +1 on password change / sign out everywhere
  "failed_logins"            INTEGER  NOT NULL DEFAULT 0,
  "locked_until"             TEXT,
  "role"                     INTEGER  NOT NULL CHECK ("role" >= 1),  -- AdminRole: 1 super, 2 manager, 3 support
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "last_login_at"            TEXT,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "platform_admins_updated_at" AFTER UPDATE ON "platform_admins" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "platform_admins" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;


-- Plans the product sells (today: price per branch per month). Lets pricing change without code.
CREATE TABLE IF NOT EXISTS "plans" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "code"                     TEXT     NOT NULL UNIQUE,  -- max 30 · standard | …
  "name"                     TEXT     NOT NULL,  -- max 80
  "price_per_branch_month_minor" INTEGER  NOT NULL,
  "features_json"            TEXT,  -- feature keys included
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "plans_updated_at" AFTER UPDATE ON "plans" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "plans" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;


-- Key / value platform settings: 'pricing', 'reminders', 'whatsapp', …
-- 'reminders' = {enabled, daysBefore, supportContact, lastRunOn} — the daily Cron skips when lastRunOn = today,
-- so a re-run never sends twice. Reminder history = whatsapp_messages (kind 'renewal_reminder').
CREATE TABLE IF NOT EXISTS "platform_settings" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "setting_key"              TEXT     NOT NULL UNIQUE,  -- max 60
  "value_json"               TEXT     NOT NULL,
  "schema_version"           INTEGER  NOT NULL DEFAULT 1,
  "updated_by"               INTEGER  REFERENCES "platform_admins"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "platform_settings_updated_at" AFTER UPDATE ON "platform_settings" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "platform_settings" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_platform_settings_updated_by" ON "platform_settings" ("updated_by");

CREATE TABLE IF NOT EXISTS "feature_flags" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "feature_key"              TEXT     NOT NULL UNIQUE,  -- max 40 · whatsapp | …
  "name"                     TEXT     NOT NULL,  -- max 80
  "rollout"                  INTEGER  NOT NULL DEFAULT 1 CHECK ("rollout" >= 1),  -- Rollout: 1 off, 2 selected, 3 all
  "description"              TEXT,  -- max 255
  "updated_by"               INTEGER  REFERENCES "platform_admins"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "feature_flags_updated_at" AFTER UPDATE ON "feature_flags" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "feature_flags" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_feature_flags_updated_by" ON "feature_flags" ("updated_by");

CREATE TABLE IF NOT EXISTS "businesses" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "name"                     TEXT     NOT NULL,  -- max 150
  "category"                 INTEGER  NOT NULL CHECK ("category" >= 1),  -- BusinessCategory: 1 retail, 2 food, 3 restaurant, 4 service
  "sub_type"                 TEXT     NOT NULL,  -- max 60 · Supermarket | Hardware | Fast Food | Bakery | … (picks terminology & defaults)
  "phone"                    TEXT,  -- max 16 · E.164
  "email"                    TEXT,  -- max 150
  "address"                  TEXT,  -- max 255
  "city"                     TEXT,  -- max 80
  "state"                    TEXT,  -- max 80
  "country_code"             TEXT     NOT NULL DEFAULT 'IN',  -- max 2 · ISO 3166
  "currency_code"            TEXT     NOT NULL DEFAULT 'INR',  -- max 3 · ISO 4217
  "currency_symbol"          TEXT     NOT NULL DEFAULT '₹',  -- max 5
  "timezone"                 TEXT     NOT NULL DEFAULT 'Asia/Kolkata',  -- max 40
  "gstin"                    TEXT,  -- max 15
  "logo_media_id"            INTEGER,  -- → media_files.ROWID (no FK: media_files refers back here). NULL = the app shows the default icon for category / sub_type; no emoji column.
  "status"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("status" >= 1),  -- BusinessStatus: 1 active, 2 deactivated
  "plan_id"                  INTEGER  REFERENCES "plans"("id") ON DELETE SET NULL,
  "max_branches"             INTEGER  NOT NULL DEFAULT 1,
  "subscription_start_at"    TEXT,
  "subscription_end_at"      TEXT,  -- after this: read-only
  "reminders_paused"         INTEGER  NOT NULL DEFAULT 0 CHECK ("reminders_paused" IN (0, 1)),
  "admin_note"               TEXT,  -- max 255 · product admin only, never shown to the customer
  "onboarded_at"             TEXT,
  "deleted_at"               TEXT,  -- set when the admin deletes the customer (download the export first) Directory for the product admin's customer list (copies kept up to date by the API, so the list never has to open every shop's own database):
  "owner_user_id"            INTEGER,  -- → users.ROWID of the owner login (in the shop's database)
  "owner_name"               TEXT,  -- max 120
  "owner_username"           TEXT,  -- max 40
  "owner_phone"              TEXT,  -- max 16 · E.164, the owner's sign-in mobile (renewal reminders go here)
  "owner_email"              TEXT,  -- max 150
  "branches_used"            INTEGER  NOT NULL DEFAULT 1,
  "last_login_at"            TEXT,  -- newest sign-in of any user of this shop
  "last_activity_at"         TEXT,  -- newest change (updated at most once an hour)
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "businesses_updated_at" AFTER UPDATE ON "businesses" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "businesses" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_businesses_plan_id" ON "businesses" ("plan_id");

-- Secrets (WhatsApp tokens etc.) — the only place they are kept. Never returned to a browser.
CREATE TABLE IF NOT EXISTS "secrets" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "owner_type"               INTEGER  NOT NULL CHECK ("owner_type" >= 1),  -- SecretOwner: 1 platform, 2 business
  "business_id"              INTEGER  REFERENCES "businesses"("id") ON DELETE CASCADE,  -- NULL for platform secrets
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- SecretKind: 1 whatsapp_token
  "value"                    TEXT     NOT NULL,  -- AES-256-GCM ciphertext (encrypted in the API)
  "last4"                    TEXT,  -- max 4
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 120 · '<owner_type>:<business_id|0>:<kind>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "secrets_updated_at" AFTER UPDATE ON "secrets" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "secrets" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_secrets_business_id" ON "secrets" ("business_id");

CREATE TABLE IF NOT EXISTS "subscription_periods" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL REFERENCES "businesses"("id") ON DELETE CASCADE,
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- PeriodKind: 1 new, 2 renew, 3 extend, 4 change
  "start_at"                 TEXT     NOT NULL,
  "end_at"                   TEXT     NOT NULL,
  "months"                   INTEGER,  -- NULL for custom dates
  "branches"                 INTEGER  NOT NULL,
  "price_per_branch_minor"   INTEGER  NOT NULL,  -- rate used (prices can change later)
  "amount_minor"             INTEGER  NOT NULL,
  "payment_ref"              TEXT,  -- max 80
  "note"                     TEXT,  -- max 255
  "admin_id"                 INTEGER  REFERENCES "platform_admins"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "subscription_periods_updated_at" AFTER UPDATE ON "subscription_periods" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "subscription_periods" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_subscription_periods_business_id_created_at" ON "subscription_periods" ("business_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_subscription_periods_admin_id" ON "subscription_periods" ("admin_id");

-- Features released to selected customers (feature_flags.rollout = 'selected').
CREATE TABLE IF NOT EXISTS "feature_flag_businesses" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "feature_flag_id"          INTEGER  NOT NULL REFERENCES "feature_flags"("id") ON DELETE CASCADE,
  "business_id"              INTEGER  NOT NULL REFERENCES "businesses"("id") ON DELETE CASCADE,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<feature_flag_id>:<business_id>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "feature_flag_businesses_updated_at" AFTER UPDATE ON "feature_flag_businesses" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "feature_flag_businesses" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_feature_flag_businesses_feature_flag_id" ON "feature_flag_businesses" ("feature_flag_id");
CREATE INDEX IF NOT EXISTS "ix_feature_flag_businesses_business_id" ON "feature_flag_businesses" ("business_id");

-- Message templates — the customer's (business_id set) and the platform's (business_id NULL).
CREATE TABLE IF NOT EXISTS "whatsapp_templates" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  REFERENCES "businesses"("id") ON DELETE CASCADE,
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- WaTemplateKind: 1 bill, 2 offer, 3 renewal_reminder
  "language"                 TEXT     NOT NULL,  -- max 5 · en | ta
  "body"                     TEXT     NOT NULL,
  "attach"                   INTEGER  NOT NULL DEFAULT 0 CHECK ("attach" IN (0, 1)),  -- PDF / poster header
  "meta_template_name"       TEXT,  -- max 80
  "status"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("status" >= 1),  -- WaTemplateStatus: 1 draft, 2 pending, 3 approved, 4 rejected
  "reject_reason"            TEXT,  -- max 255
  "submitted_at"             TEXT,
  "approved_at"              TEXT,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<business_id|platform>:<kind>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "whatsapp_templates_updated_at" AFTER UPDATE ON "whatsapp_templates" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "whatsapp_templates" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_whatsapp_templates_business_id" ON "whatsapp_templates" ("business_id");

-- What the product admin team did.
CREATE TABLE IF NOT EXISTS "admin_audit_logs" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "admin_id"                 INTEGER  REFERENCES "platform_admins"("id") ON DELETE SET NULL,
  "admin_name"               TEXT     NOT NULL,  -- max 120 · snapshot
  "business_id"              INTEGER  REFERENCES "businesses"("id") ON DELETE SET NULL,  -- NULL after the customer is deleted
  "business_name"            TEXT,  -- max 150 · snapshot (kept after delete)
  "action"                   INTEGER  NOT NULL CHECK ("action" >= 1),  -- AdminAction: 1 create, 2 update, 3 password, 4 renew, 5 branch_limit, 6 activate, 7 deactivate, 8 delete, 9 settings, 10 login, 11 export, 12 reminder, 13 support_start, 14 support_end, 15 admin_create, 16 admin_update, 17 feature
  "detail"                   TEXT,  -- max 255
  "ip"                       TEXT,  -- max 45
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "admin_audit_logs_updated_at" AFTER UPDATE ON "admin_audit_logs" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "admin_audit_logs" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_admin_audit_logs_business_id_created_at" ON "admin_audit_logs" ("business_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_admin_audit_logs_created_at" ON "admin_audit_logs" ("created_at");
CREATE INDEX IF NOT EXISTS "ix_admin_audit_logs_admin_id" ON "admin_audit_logs" ("admin_id");

-- Sign-in names → which shop they belong to. Usernames, mobile numbers and emails are unique across every
-- shop and admin, and with one database per shop this is how sign-in finds the right one.
CREATE TABLE IF NOT EXISTS "login_names" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "login"                    TEXT     NOT NULL UNIQUE,  -- max 160 · lower-case username, E.164 mobile or lower-case email
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- LoginKind: 1 username, 2 phone, 3 email
  "business_id"              INTEGER  NOT NULL REFERENCES "businesses"("id") ON DELETE CASCADE,
  "user_id"                  INTEGER  NOT NULL,  -- → users.ROWID in the shop's database
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "login_names_updated_at" AFTER UPDATE ON "login_names" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "login_names" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_login_names_business_id" ON "login_names" ("business_id");

-- Where each shop's own database is (Turso: one database per shop). Not used when everything is in one database.
CREATE TABLE IF NOT EXISTS "shop_databases" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL UNIQUE REFERENCES "businesses"("id") ON DELETE CASCADE,
  "db_name"                  TEXT     NOT NULL UNIQUE,  -- max 64
  "db_url"                   TEXT,  -- max 255
  "db_token"                 TEXT,  -- AES-256-GCM ciphertext (encrypted in the API) · this database's own access token (Turso), encrypted
  "schema_version"           TEXT,  -- max 40 · newest migration applied
  "status"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("status" >= 1),  -- ShopDbStatus: 1 creating, 2 ready, 3 failed, 4 deleting
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "shop_databases_updated_at" AFTER UPDATE ON "shop_databases" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "shop_databases" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;


-- Images and files stored in Stratus.
CREATE TABLE IF NOT EXISTS "media_files" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  REFERENCES "businesses"("id") ON DELETE CASCADE,  -- NULL = platform file
  "purpose"                  INTEGER  NOT NULL CHECK ("purpose" >= 1),  -- MediaPurpose: 1 product, 2 category, 3 logo, 4 ticket, 5 poster
  "bucket"                   TEXT     NOT NULL,  -- max 60
  "object_key"               TEXT     NOT NULL UNIQUE,  -- max 255 · '<business_id>/products/<uuid>.webp'
  "thumb_key"                TEXT,  -- max 255
  "content_type"             TEXT     NOT NULL,  -- max 40 · image/webp | application/zip | …
  "bytes"                    INTEGER  NOT NULL,  -- photos ≤ 51,200
  "width"                    INTEGER,
  "height"                   INTEGER,
  "original_bytes"           INTEGER,
  "created_by"               INTEGER,  -- → users.id in the shop database (checked by the API)
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "media_files_updated_at" AFTER UPDATE ON "media_files" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "media_files" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_media_files_business_id" ON "media_files" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_media_files_created_by" ON "media_files" ("created_by");

CREATE TABLE IF NOT EXISTS "support_tickets" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL REFERENCES "businesses"("id") ON DELETE CASCADE,
  "user_id"                  INTEGER,  -- → users.id in the shop database (checked by the API)
  "number"                   TEXT     NOT NULL UNIQUE,  -- max 20 · T-1001
  "subject"                  TEXT     NOT NULL,  -- max 120
  "category"                 INTEGER  NOT NULL CHECK ("category" >= 1),  -- TicketCategory: 1 billing, 2 printer, 3 stock, 4 whatsapp, 5 account, 6 other
  "priority"                 INTEGER  NOT NULL DEFAULT 2 CHECK ("priority" >= 1),  -- TicketPriority: 1 low, 2 normal, 3 high, 4 urgent
  "status"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("status" >= 1),  -- TicketStatus: 1 open, 2 in_progress, 3 waiting, 4 resolved, 5 closed
  "assigned_to"              INTEGER  REFERENCES "platform_admins"("id") ON DELETE SET NULL,
  "page"                     TEXT,  -- max 200
  "browser"                  TEXT,  -- max 255
  "app_version"              TEXT,  -- max 20
  "device_id"                INTEGER,  -- → devices.id in the shop database (checked by the API)
  "user_name"                TEXT,  -- max 120 · snapshot of who raised it (the admin inbox reads no shop data)
  "user_phone"               TEXT,  -- max 16
  "unread_for_admin"         INTEGER  NOT NULL DEFAULT 1 CHECK ("unread_for_admin" IN (0, 1)),
  "unread_for_customer"      INTEGER  NOT NULL DEFAULT 0 CHECK ("unread_for_customer" IN (0, 1)),
  "last_message_at"          TEXT     NOT NULL,
  "resolved_at"              TEXT,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "support_tickets_updated_at" AFTER UPDATE ON "support_tickets" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "support_tickets" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_support_tickets_business_id_last_message_at" ON "support_tickets" ("business_id", "last_message_at");
CREATE INDEX IF NOT EXISTS "ix_support_tickets_status_last_message_at" ON "support_tickets" ("status", "last_message_at");
CREATE INDEX IF NOT EXISTS "ix_support_tickets_user_id" ON "support_tickets" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_support_tickets_assigned_to" ON "support_tickets" ("assigned_to");
CREATE INDEX IF NOT EXISTS "ix_support_tickets_device_id" ON "support_tickets" ("device_id");

CREATE TABLE IF NOT EXISTS "ticket_messages" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "ticket_id"                INTEGER  NOT NULL REFERENCES "support_tickets"("id") ON DELETE CASCADE,
  "from_side"                INTEGER  NOT NULL CHECK ("from_side" >= 1),  -- TicketSide: 1 customer, 2 admin
  "user_id"                  INTEGER,  -- → users.id in the shop database (checked by the API)
  "admin_id"                 INTEGER  REFERENCES "platform_admins"("id") ON DELETE SET NULL,
  "author_name"              TEXT     NOT NULL,  -- max 120
  "body"                     TEXT,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "ticket_messages_updated_at" AFTER UPDATE ON "ticket_messages" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "ticket_messages" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_ticket_messages_ticket_id_created_at" ON "ticket_messages" ("ticket_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_ticket_messages_user_id" ON "ticket_messages" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_ticket_messages_admin_id" ON "ticket_messages" ("admin_id");

-- Every WhatsApp message: bills, offers, tests, and platform renewal reminders (business_id = customer).
CREATE TABLE IF NOT EXISTS "whatsapp_messages" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  REFERENCES "businesses"("id") ON DELETE CASCADE,
  "sender"                   INTEGER  NOT NULL CHECK ("sender" >= 1),  -- WaSender: 1 business, 2 platform
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- WaMessageKind: 1 bill, 2 offer, 3 test, 4 renewal_reminder
  "to_number"                TEXT     NOT NULL,  -- max 16
  "customer_id"              INTEGER,  -- → customers.id in the shop database (checked by the API)
  "order_id"                 INTEGER,  -- → orders.id in the shop database (checked by the API)
  "campaign_id"              INTEGER,  -- → campaigns.id in the shop database (checked by the API)
  "template_id"              INTEGER  REFERENCES "whatsapp_templates"("id") ON DELETE SET NULL,
  "body"                     TEXT     NOT NULL,
  "attachment_media_id"      INTEGER  REFERENCES "media_files"("id") ON DELETE SET NULL,
  "meta_message_id"          TEXT     UNIQUE,  -- max 80 · updated by Meta's webhook
  "status"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("status" >= 1),  -- WaMessageStatus: 1 queued, 2 sent, 3 delivered, 4 read, 5 failed
  "error"                    TEXT,  -- max 255
  "status_at"                TEXT,
  "created_by"               INTEGER,  -- → users.id in the shop database (checked by the API)
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "whatsapp_messages_updated_at" AFTER UPDATE ON "whatsapp_messages" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "whatsapp_messages" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_whatsapp_messages_business_id_created_at" ON "whatsapp_messages" ("business_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_whatsapp_messages_campaign_id" ON "whatsapp_messages" ("campaign_id");
CREATE INDEX IF NOT EXISTS "ix_whatsapp_messages_customer_id" ON "whatsapp_messages" ("customer_id");
CREATE INDEX IF NOT EXISTS "ix_whatsapp_messages_order_id" ON "whatsapp_messages" ("order_id");
CREATE INDEX IF NOT EXISTS "ix_whatsapp_messages_template_id" ON "whatsapp_messages" ("template_id");
CREATE INDEX IF NOT EXISTS "ix_whatsapp_messages_attachment_media_id" ON "whatsapp_messages" ("attachment_media_id");
CREATE INDEX IF NOT EXISTS "ix_whatsapp_messages_created_by" ON "whatsapp_messages" ("created_by");

CREATE TABLE IF NOT EXISTS "ticket_attachments" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "message_id"               INTEGER  NOT NULL REFERENCES "ticket_messages"("id") ON DELETE CASCADE,
  "media_id"                 INTEGER  NOT NULL REFERENCES "media_files"("id") ON DELETE CASCADE,  -- screenshots ≤ 1600 px / 200 KB, up to 5
  "sort_order"               INTEGER  NOT NULL DEFAULT 0,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "ticket_attachments_updated_at" AFTER UPDATE ON "ticket_attachments" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "ticket_attachments" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_ticket_attachments_message_id" ON "ticket_attachments" ("message_id");
CREATE INDEX IF NOT EXISTS "ix_ticket_attachments_media_id" ON "ticket_attachments" ("media_id");

-- =====================================================================================================
--  Added for Turso
-- =====================================================================================================

-- Which migration files have run on this database.
CREATE TABLE IF NOT EXISTS "schema_migrations" (
  "version"                  TEXT     PRIMARY KEY,  -- file name, e.g. 0001_init
  "applied_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- Small shared cache for every API instance (Turso setup): QR menu / report copies, version stamps, rate limits.
-- Replaces Catalyst Cache there (cheaper: a Turso row read costs almost nothing). Old rows are removed as they expire.
CREATE TABLE IF NOT EXISTS "kv_cache" (
  "key"                      TEXT     PRIMARY KEY,
  "value"                    TEXT     NOT NULL,
  "expires_at"               INTEGER  NOT NULL   -- ms since 1970
) STRICT;
CREATE INDEX IF NOT EXISTS "ix_kv_cache_expires_at" ON "kv_cache" ("expires_at");
